/**
 * Local-disk file sink: one file per key under a directory you own.
 *
 * The default off Cursor-managed hosting. Paths are real, so the harness can
 * open a file with its ordinary tools — that is why this reports
 * `materialized` — and there are no etags, so `conflictDetection` is honestly
 * false and concurrent writers are last-writer-wins.
 */
import { randomUUID } from "node:crypto";
import { mkdir, readdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { join, relative, resolve, sep } from "node:path";
import { describeErrorCode } from "../internal/describe-error.js";
import { FilePathRejectedError, } from "../files.js";
/**
 * Default sink: one file per key under the state root, written atomically.
 *
 * Reports `materialized` because the paths are real — that is what lets the
 * harness read a file with its ordinary tools — and reports no `etags`, so
 * `host.files.capabilities.conflictDetection` is honestly false and concurrent
 * writers are last-writer-wins.
 */
export function localFiles(options) {
    const root = resolve(options.filesRoot);
    const stripPrefix = options.stripKeyPrefix ?? "";
    const pathForKey = (key) => {
        const rel = stripPrefix !== "" && key.startsWith(stripPrefix) ? key.slice(stripPrefix.length) : key;
        const candidate = resolve(root, rel);
        const within = relative(root, candidate);
        if (within === "" || within === ".." || within.startsWith(`..${sep}`)) {
            throw new FilePathRejectedError(`host.files key does not resolve under the state root: ${key}`);
        }
        return candidate;
    };
    const entryFor = async (key, absPath) => {
        try {
            const info = await stat(absPath);
            if (!info.isFile()) {
                return undefined;
            }
            return { key, size: info.size, mtimeMs: info.mtimeMs };
        }
        catch (error) {
            if (describeErrorCode(error) === "ENOENT") {
                return undefined;
            }
            throw error;
        }
    };
    return {
        capabilities: { materialized: true },
        materializedPath: (key) => pathForKey(key),
        async put(key, body) {
            const target = pathForKey(key);
            await mkdir(join(target, ".."), { recursive: true });
            // Same-directory temp + rename: a reader either sees the previous value
            // or the whole new one, never a half-written file.
            const tmp = join(target, "..", `.tmp-${randomUUID()}`);
            try {
                await writeFile(tmp, body);
                await rename(tmp, target);
            }
            catch (error) {
                await rm(tmp, { force: true });
                throw error;
            }
        },
        async get(key) {
            try {
                return { body: new Uint8Array(await readFile(pathForKey(key))) };
            }
            catch (error) {
                const code = describeErrorCode(error);
                if (code === "ENOENT" || code === "EISDIR") {
                    return undefined;
                }
                throw error;
            }
        },
        async delete(key) {
            await rm(pathForKey(key), { force: true });
        },
        async stat(key) {
            return await entryFor(key, pathForKey(key));
        },
        async list(prefix) {
            // Walk the deepest existing directory at or above the prefix, then keep
            // the keys that actually start with it — `prefix` is a key prefix, not a
            // directory, so `notes/sum` must match `notes/summary.md`.
            const prefixPath = pathForKey(prefix);
            const searchRoot = (await isDirectory(prefixPath)) ? prefixPath : join(prefixPath, "..");
            const out = [];
            for await (const absPath of walkFiles(searchRoot)) {
                const key = `${stripPrefix}${relative(root, absPath).split(sep).join("/")}`;
                if (!key.startsWith(prefix)) {
                    continue;
                }
                const entry = await entryFor(key, absPath);
                if (entry !== undefined) {
                    out.push(entry);
                }
            }
            return out.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
        },
    };
}
async function isDirectory(absPath) {
    try {
        return (await stat(absPath)).isDirectory();
    }
    catch {
        return false;
    }
}
async function* walkFiles(dir) {
    let entries;
    try {
        entries = await readdir(dir, { withFileTypes: true });
    }
    catch (error) {
        if (describeErrorCode(error) === "ENOENT") {
            return;
        }
        throw error;
    }
    for (const entry of entries) {
        const abs = join(dir, entry.name);
        if (entry.isDirectory()) {
            yield* walkFiles(abs);
        }
        else if (entry.isFile() && !entry.name.startsWith(".tmp-")) {
            yield abs;
        }
    }
}
